 4	public final class BubbleSort {
 5	
 6	    private BubbleSort() {
 7	        // Utility class.
 8	    }
 9	
10	    public static void sortInPlace(int[] values) {
11	        validate(values);
12	        sortValuesInPlace(values);
13	    }
14	
15	    public static int[] sortedCopy(int[] values) {
16	        validate(values);
17	
18	        int[] copy = Arrays.copyOf(values, values.length);
19	        sortValuesInPlace(copy);
20	        return copy;
21	    }
22	
23	    private static int[] createDemoValues() {
24	        return new int[] { 64, 34, 25, 12, 22, 11, 90 };
25	    }
26	
27	    private static void validate(int[] values) {
28	        if (values == null) {
29	            throw new IllegalArgumentException("values must not be null");
30	        }
31	    }
32	
33	    private static void sortValuesInPlace(int[] values) {
34	        int end = values.length - 1;
35	        while (end > 0) {
36	            int lastSwapIndex = bubblePass(values, end);
37	            if (lastSwapIndex == 0) {
38	                return;
39	            }
40	            end = lastSwapIndex - 1;
41	        }
42	    }
43	
44	    private static int bubblePass(int[] values, int endExclusive) {
45	        int lastSwapIndex = 0;
46	
47	        for (int index = 0; index < endExclusive; index++) {
48	            if (isOutOfOrder(values, index)) {
49	                swap(values, index, index + 1);
50	                lastSwapIndex = index + 1;
51	            }
52	        }
53	
54	        return lastSwapIndex;
55	    }
56	
57	    private static boolean isOutOfOrder(int[] values, int index) {
58	        return values[index] > values[index + 1];
59	    }
60	
61	    private static void swap(int[] values, int leftIndex, int rightIndex) {
62	        int temp = values[leftIndex];
63	        values[leftIndex] = values[rightIndex];
64	        values[rightIndex] = temp;
65	    }
66	
67	    private static String formatArray(int[] values) {
68	        StringJoiner joiner = new StringJoiner(" ");
69	
70	        for (int value : values) {
71	            joiner.add(Integer.toString(value));
72	        }
73	
74	        return joiner.toString();
75	    }
76	
77	    private static void runDemo() {
78	        int[] values = createDemoValues();
79	        sortInPlace(values);
80	        System.out.println("Sorted array: ");
81	        System.out.println(formatArray(values));
82	    }
83	
